function Logo() { return <div className="brand"><div className="brand-mark"><BookOpenCheck size={22} /></div><span>MyBiz<span className="brand-accent">Vault</span></span></div> }
function StatusPill({ children, tone = 'neutral' }: { children: ReactNode; tone?: 'neutral' | 'green' | 'amber' | 'blue' }) { return <span className={`status-pill status-${tone}`}>{children}</span> }
function SectionHeading({ eyebrow, title, action }: { eyebrow?: string; title: string; action?: ReactNode }) { return <div className="section-heading"><div>{eyebrow && <p className="eyebrow">{eyebrow}</p>}<h2>{title}</h2></div>{action}</div> }
function EmptyState({ title, detail, action }: { title: string; detail: string; action?: ReactNode }) { return <div className="empty-state"><div className="empty-icon"><FileText size={23} /></div><h3>{title}</h3><p>{detail}</p>{action}</div> }
function ErrorBlock({ error }: { error: unknown }) { return <div role="alert" className="form-error">{apiError(error)}</div> }
function SectionIntro({ label, title, description, action }: { label: string; title: string; description: string; action?: ReactNode }) { return <div className="section-intro"><div><p className="eyebrow">{label}</p><h1>{title}</h1><p>{description}</p></div>{action}</div> }

type AuthFields = { full_name: string; business_name: string; email: string; password: string }
const authSchema = z.object({ full_name: z.string().trim().min(2), business_name: z.string().trim().min(2), email: z.email(), password: z.string().min(12) })

function AuthScreen({ onSuccess }: { onSuccess: () => void }) {
  const [registering, setRegistering] = useState(false)
  const [error, setError] = useState<unknown>(null)
  const [busy, setBusy] = useState(false)
  const { register, handleSubmit, reset } = useForm<AuthFields>()
  const submit = handleSubmit(async values => {
    setError(null)
    if (!z.email().safeParse(values.email).success || values.password.length < (registering ? 12 : 1)) {
      setError(new Error('Enter a valid email and password. New passwords need at least 12 characters.'))
      return
    }
    if (registering && !authSchema.safeParse(values).success) {
      setError(new Error('Complete every field. Names need at least two characters.'))
      return
    }
    setBusy(true)
    try {
      if (registering) await registerOwner(values)
      else await login({ email: values.email, password: values.password })
      onSuccess()
    } catch (failure) { setError(failure) } finally { setBusy(false) }
  })
  return <div className="auth-page"><div className="auth-aside"><Logo /><div><p className="eyebrow">COMMERCIAL CLARITY</p><h1>Keep every business promise in view.</h1><p>Document transactions, follow commitments, and find the records you need when questions arise.</p></div><div className="auth-aside-foot"><ShieldCheck size={19} /> Built for clear business records</div></div><main className="auth-main"><div className="auth-card"><div className="auth-mobile-logo"><Logo /></div><p className="eyebrow">BUSINESS ACCESS</p><h2>{registering ? 'Create your workspace' : 'Welcome back'}</h2><p>{registering ? 'Set up an owner account for your business.' : 'Sign in to your business workspace.'}</p><form onSubmit={submit} className="form-stack">{registering && <><label>Full name<input autoComplete="name" {...register('full_name')} required /></label><label>Business name<input autoComplete="organization" {...register('business_name')} required /></label></>}<label>Email address<input type="email" autoComplete="email" {...register('email')} required /></label><label>Password<input type="password" autoComplete={registering ? 'new-password' : 'current-password'} minLength={registering ? 12 : 1} {...register('password')} required /></label>{Boolean(error) && <ErrorBlock error={error} />}<Button type="submit" disabled={busy}>{busy ? 'Please wait…' : registering ? 'Create business account' : 'Sign in'}</Button></form><div className="auth-switch">{registering ? 'Already have an account?' : 'New to MyBizVault?'} <button type="button" onClick={() => { setRegistering(!registering); setError(null); reset() }}>{registering ? 'Sign in' : 'Create an account'}</button></div><p className="auth-note">Business owners and authorised staff only. Customers never need an account.</p></div></main></div>
}

function HealthIndicator() {
  const { data, isPending, isError } = useQuery({ queryKey: ['health'], queryFn: getHealth, refetchInterval: 30000 })
  return <span className={`health ${data?.status === 'ok' ? 'health-good' : isError ? 'health-error' : ''}`}><span className="health-dot" />{isPending ? 'Checking API' : isError ? 'API unavailable' : 'API connected'}</span>
}

