function TransactionDetailPage({ membership }: { membership: Membership }) {
  const { transactionId = '' } = useParams()
  const [preview, setPreview] = useState<string | null>(null)
  const [pdfError, setPdfError] = useState<unknown>(null)
  const { data, isPending, error } = useQuery({ queryKey: ['transaction', membership.business_id, transactionId],
    queryFn: () => getTransaction(membership.business_id, transactionId), enabled: membership.can_view_transactions && !!transactionId })
  const { data: agreement } = useQuery({ queryKey: ['agreement', membership.business_id, data?.agreement?.id],
    queryFn: () => getAgreement(membership.business_id, data!.agreement!.id),
    enabled: membership.can_manage_agreements && !!data?.agreement })
  useEffect(() => () => { if (preview) URL.revokeObjectURL(preview) }, [preview])
  const openPdf = async (kind: 'receipt' | 'agreement', id: string, mode: 'preview' | 'download' | 'share', version?: number) => {
    setPdfError(null)
    try {
      const blob = kind === 'receipt'
        ? await getReceiptPdf(membership.business_id, transactionId, id)
        : await getAgreementPdf(membership.business_id, id, version)
      const name = kind === 'receipt' ? `receipt-${id}.pdf` : `agreement-${id}-v${version}.pdf`
      if (mode === 'share' && navigator.canShare?.({ files: [new File([blob], name, { type: 'application/pdf' })] })) {
        await navigator.share({ files: [new File([blob], name, { type: 'application/pdf' })], title: name })
        return
      }
      const url = URL.createObjectURL(blob)
      if (mode === 'preview') setPreview(url)
      else { const link = document.createElement('a'); link.href = url; link.download = name; link.click(); setTimeout(() => URL.revokeObjectURL(url), 60000) }
    } catch (failure) { setPdfError(failure) }
  }
  if (!membership.can_view_transactions) return <EmptyState title="Access not granted" detail="Ask the business owner for transaction access." />
  return <><SectionIntro label="TRANSACTION RECORD" title={data ? data.counterparty_name : 'Transaction'} description="Receipts, obligations and approval history for this sale." action={<Link className="text-link" to="/transactions">All transactions</Link>} />
    {isPending ? <p>Loading transaction…</p> : error ? <ErrorBlock error={error} /> : data && <div className="settings-stack">
      <div className="card module-card"><h2>{data.description}</h2><p>{data.transaction_date} · {ugx(data.total_ugx)} total · {ugx(data.balance_ugx)} outstanding</p><p>Customer: {data.counterparty_name}{data.customer_phone && ` · ${data.customer_phone}`}{data.customer_email && ` · ${data.customer_email}`}</p><p>Original deadline: {data.due_date || 'None'} · Working deadline: {data.effective_due_date || 'None'}</p><p>Delivery: {data.delivery_notes || 'Not recorded'}</p><h3>Items</h3>{data.line_items.map((item, index) => <p key={index}>{item.description} ? {item.quantity} ? {ugx(item.unit_price_ugx)} = {ugx(item.quantity * item.unit_price_ugx)}</p>)}</div>
      <div className="card module-card"><h2>Payment receipts</h2><p className="field-hint">Payment entries are business records. Receipt issue and agreement acceptance have separate statuses.</p>{data.receipts.length ? data.receipts.map(receipt => <div className="module-item" key={receipt.id}><div><strong>{receipt.kind === 'initial' ? 'Initial payment' : 'Later payment'} · {ugx(receipt.amount_ugx)}</strong><small>{receipt.payment_date} · {receipt.payment_status_at_issue.replaceAll('_', ' ')}</small></div><Button variant="outline" size="small" onClick={() => openPdf('receipt', receipt.id, 'preview')}>Preview PDF</Button><Button variant="outline" size="small" onClick={() => openPdf('receipt', receipt.id, 'download')}>Download</Button><Button variant="outline" size="small" onClick={() => openPdf('receipt', receipt.id, 'share')}>Share</Button></div>) : <p>No payment has been recorded, so no receipt is available.</p>}{data.payments.map(payment => <p key={payment.id}>Payment {ugx(payment.amount_ugx)} on {payment.paid_on}: <strong>{payment.status}</strong> (business recorded)</p>)}</div>
      <div className="card module-card"><h2>Outstanding obligation agreement</h2>{data.agreement ? <><p>Agreement approval: <strong>{data.agreement.status.replaceAll('_', ' ')}</strong> · Version {data.agreement.current_version}</p>{membership.can_manage_agreements && <><Link className="text-link" to={`/agreements?agreement=${data.agreement.id}`}>Open agreement and approval tools</Link><div className="form-actions"><Button variant="outline" onClick={() => openPdf('agreement', data.agreement!.id, 'preview', data.agreement!.current_version)}>Preview PDF</Button><Button variant="outline" onClick={() => openPdf('agreement', data.agreement!.id, 'download', data.agreement!.current_version)}>Download</Button><Button variant="outline" onClick={() => openPdf('agreement', data.agreement!.id, 'share', data.agreement!.current_version)}>Share</Button></div>{agreement?.versions.map(version => <div key={version.id}><span>Version {version.version} · {new Date(version.created_at).toLocaleString()}</span> <Button variant="ghost" size="small" onClick={() => openPdf('agreement', data.agreement!.id, 'preview', version.version)}>Preview</Button></div>)}<h3>Agreement approval history</h3>{agreement?.events.length ? agreement.events.map((event, index) => <p key={index}>{event.action} · {event.verification_method.replaceAll('_', ' ')} · {new Date(event.created_at).toLocaleString()}</p>) : <p>No external response recorded.</p>}</>}</> : <p>No agreement is needed for a fully paid transaction.</p>}</div>
      <div className="card module-card"><h2>Payment and proposal history</h2>{data.approval_history.length ? data.approval_history.map(event => <p key={event.id}>{event.action.replaceAll('_', ' ')} · {new Date(event.created_at).toLocaleString()}{event.note && ` · ${event.note}`}</p>) : <p>No later activity recorded.</p>}</div>
      <div className="card module-card"><h2>Communication log</h2>{data.communications.length ? data.communications.map(item => <p key={item.id}>{item.channel} to {item.recipient_masked}: <strong>{item.status}</strong> via {item.provider} · {new Date(item.updated_at).toLocaleString()}</p>) : <p>No messages have been sent from this transaction.</p>}</div>
      {Boolean(pdfError) && <ErrorBlock error={pdfError} />}{preview && <div className="card module-card"><Button variant="outline" onClick={() => setPreview(null)}>Close PDF preview</Button><iframe title="Document PDF preview" src={preview} style={{ width: '100%', height: '70vh', border: 0 }} /></div>}
    </div>}</>
}

type TransactionFields = { counterparty_id: string; description: string; line_items: { description: string; quantity: number; unit_price_ugx: number }[]; transaction_date: string; total_ugx: number; paid_ugx: number; due_date: string; delivery_notes: string }
const transactionSchema = z.object({ counterparty_id: z.string().min(1), description: z.string().trim().min(3), line_items: z.array(z.object({ description: z.string().trim().min(2), quantity: z.number().int().positive(), unit_price_ugx: z.number().int().positive() })).max(30), transaction_date: z.iso.date(), total_ugx: z.number().int().positive().max(1_000_000_000_000), paid_ugx: z.number().int().nonnegative().max(1_000_000_000_000), due_date: z.string(), delivery_notes: z.string() }).refine(value => value.paid_ugx <= value.total_ugx, 'Amount paid cannot exceed total value').refine(value => value.paid_ugx === value.total_ugx || !!value.due_date, 'Add a deadline when a balance remains').refine(value => !value.line_items.length || value.line_items.reduce((sum, item) => sum + item.quantity * item.unit_price_ugx, 0) === value.total_ugx, 'Itemized amounts must equal the transaction total')

function NewTransactionPage({ membership, userId }: { membership: Membership; userId: string }) {
  const navigate = useNavigate(), queryClient = useQueryClient()
  const [error, setError] = useState<unknown>(null), [busy, setBusy] = useState(false)
  const [offlineDraft, setOfflineDraft] = useState<OfflineTransactionDraft | null>(null)
  const [draftMessage, setDraftMessage] = useState('')
  const [online, setOnline] = useState(navigator.onLine)
  const [customerOpen, setCustomerOpen] = useState(false)
  const [customerBusy, setCustomerBusy] = useState(false)
  const [newCustomer, setNewCustomer] = useState({ display_name: '', phone: '', email: '' })
  const key = draftKey(userId, membership.business_id)
  const { data: customers = [], isPending } = useQuery({ queryKey: ['customers', membership.business_id], queryFn: () => getCustomers(membership.business_id), enabled: membership.can_create_transactions })
  const { register, handleSubmit, watch, getValues, reset, setValue, control } = useForm<TransactionFields>({ defaultValues: { transaction_date: new Date().toISOString().slice(0, 10), paid_ugx: 0, due_date: '', delivery_notes: '', line_items: [] } })
  const { fields: itemFields, append: addItem, remove: removeItem } = useFieldArray({ control, name: 'line_items' })
  useEffect(() => {
    let active = true
    getTransactionDraft(key).then(draft => { if (active && draft) { setOfflineDraft(draft); reset({ ...draft.values, line_items: draft.values.line_items || [] }); setDraftMessage(draft.state === 'pending' ? 'A transaction is queued on this device. Retry when connected.' : draft.state === 'needs_review' ? 'This draft needs review before retrying.' : 'Local draft restored.') } }).catch(() => { if (active) setDraftMessage('Local draft storage is unavailable in this browser.') })
    const connected = () => setOnline(true), disconnected = () => setOnline(false)
    window.addEventListener('online', connected); window.addEventListener('offline', disconnected)
    return () => { active = false; window.removeEventListener('online', connected); window.removeEventListener('offline', disconnected) }
  }, [key, reset])
  const saveLocal = async (values: TransactionFields, state: OfflineTransactionDraft['state'], message: string, reason: string | null = null, requestId?: string) => {
    const draft: OfflineTransactionDraft = { key, user_id: userId, business_id: membership.business_id,
      request_id: requestId || offlineDraft?.request_id || crypto.randomUUID(), values, state, error: reason,
      updated_at: new Date().toISOString() }
    await putTransactionDraft(draft); setOfflineDraft(draft); setDraftMessage(message)
    return draft
  }
  const clearLocal = async () => { await deleteTransactionDraft(key); setOfflineDraft(null); setDraftMessage('Local draft removed.') }
  const sync = async (values: TransactionFields, requestId: string) => {
    const parsed = transactionSchema.safeParse(values)
    if (!parsed.success) { setError(new Error(parsed.error.issues[0]?.message ?? 'Check the draft.')); await saveLocal(values, 'needs_review', 'Review the draft before retrying.', 'Validation failed', requestId); return }
    setBusy(true); setError(null)
    try { const saved = await createTransaction(membership.business_id, { ...values, due_date: values.due_date || null, client_request_id: requestId }); await deleteTransactionDraft(key); setOfflineDraft(null); await queryClient.invalidateQueries({ queryKey: ['transactions', membership.business_id] }); navigate(`/transactions/${saved.id}`) }
    catch (failure) {
      setError(failure)
      const connectionFailure = !navigator.onLine || (axios.isAxiosError(failure) && !failure.response)
      await saveLocal(values, connectionFailure ? 'pending' : 'needs_review', connectionFailure ? 'Queued locally. Retry when connected.' : 'The server rejected this draft. Review it before retrying.', apiError(failure), requestId).catch(() => setDraftMessage('Could not save the local draft. Copy your entries before leaving.'))
    } finally { setBusy(false) }
  }
  if (!membership.can_create_transactions) return <EmptyState title="Creation access not granted" detail="Ask your business owner for permission to create transactions." />
  const total = Number(watch('total_ugx')) || 0, paid = Number(watch('paid_ugx')) || 0
  const addCustomerHere = async () => {
    if (!newCustomer.display_name.trim() || (!newCustomer.phone.trim() && !newCustomer.email.trim())) { setError(new Error('Enter a customer name and phone or email.')); return }
    setCustomerBusy(true); setError(null)
    try {
      const customer = await createCustomer(membership.business_id, newCustomer)
      queryClient.setQueryData<Counterparty[]>(['customers', membership.business_id], old => [...(old || []), customer].sort((a, b) => a.display_name.localeCompare(b.display_name)))
      setValue('counterparty_id', customer.id, { shouldValidate: true })
      setCustomerOpen(false); setNewCustomer({ display_name: '', phone: '', email: '' })
    } catch (failure) { setError(failure) } finally { setCustomerBusy(false) }
  }
  const submit = handleSubmit(async values => {
    const parsed = transactionSchema.safeParse(values)
    if (!parsed.success) { setError(new Error(parsed.error.issues[0]?.message ?? 'Check the form.')); return }
    if (!online) { try { await saveLocal(values, 'pending', 'Queued locally. Retry when connected.') } catch (failure) { setError(failure) }; return }
    await sync(values, offlineDraft?.request_id || crypto.randomUUID())
  })
  return <><SectionIntro label="NEW RECORD" title="New transaction" description="Record the sale as reported by your business. You can prepare an agreement from this record." /><div className="form-layout"><form onSubmit={submit} className="card form-card form-stack"><div className="offline-draft-panel"><strong>{online ? 'Connected' : 'Offline'} · {offlineDraft ? `${offlineDraft.state.replaceAll('_', ' ')} draft on this device` : 'No local draft'}</strong><p>{draftMessage || 'Save a local draft to keep editing on this device. Queued submissions require an explicit retry.'}</p><div className="offline-draft-actions"><Button type="button" variant="outline" onClick={() => saveLocal(getValues(), 'draft', 'Draft saved on this device.').catch(setError)} disabled={busy}>Save local draft</Button>{offlineDraft && <><Button type="button" onClick={() => sync(getValues(), offlineDraft.request_id)} disabled={busy || !online}>Retry save</Button><Button type="button" variant="ghost" onClick={() => clearLocal().catch(setError)} disabled={busy}>Remove local draft</Button></>}</div><small>Local drafts contain business details on this device. Signing out clears them. No documents are cached.</small></div><VoiceAssist apply={suggestion => { if (suggestion.description) setValue('description', suggestion.description); if (suggestion.total_ugx !== undefined) setValue('total_ugx', suggestion.total_ugx); if (suggestion.paid_ugx !== undefined) setValue('paid_ugx', suggestion.paid_ugx); if (suggestion.due_date) setValue('due_date', suggestion.due_date) }} /><label>Customer<select {...register('counterparty_id')} required><option value="">Select a customer</option>{customers.map(item => <option key={item.id} value={item.id}>{item.display_name}</option>)}</select></label><Button type="button" variant="outline" onClick={() => setCustomerOpen(!customerOpen)} disabled={!online}>{customerOpen ? 'Cancel new customer' : 'Add customer here'}</Button>{customerOpen && <div className="card form-card form-stack"><h3>New customer</h3><label>Name<input value={newCustomer.display_name} onChange={event => setNewCustomer({ ...newCustomer, display_name: event.target.value })} minLength={2} /></label><label>Phone<input type="tel" value={newCustomer.phone} onChange={event => setNewCustomer({ ...newCustomer, phone: event.target.value })} /></label><label>Email<input type="email" value={newCustomer.email} onChange={event => setNewCustomer({ ...newCustomer, email: event.target.value })} /></label><Button type="button" onClick={addCustomerHere} disabled={customerBusy}>{customerBusy ? 'Saving?' : 'Save and select customer'}</Button></div>}{isPending && <span className="field-hint">Loading customers…</span>}{!isPending && customers.length === 0 && <p className="field-hint">Add a customer here to continue.</p>}<label>Goods or services supplied<textarea rows={3} {...register('description')} required placeholder="e.g. Wholesale goods delivered" /></label><div className="form-stack"><h3>Itemized goods or services (optional)</h3><p className="field-hint">If you add items, their calculated total must match the transaction total.</p>{itemFields.map((item, index) => <div className="field-grid" key={item.id}><label>Item<input {...register(`line_items.${index}.description`)} minLength={2} required /></label><label>Quantity<input type="number" min="1" step="1" {...register(`line_items.${index}.quantity`, { valueAsNumber: true })} required /></label><label>Unit price (UGX)<input type="number" min="1" step="1" {...register(`line_items.${index}.unit_price_ugx`, { valueAsNumber: true })} required /></label><Button type="button" variant="ghost" onClick={() => removeItem(index)}>Remove item</Button></div>)}<Button type="button" variant="outline" onClick={() => addItem({ description: "", quantity: 1, unit_price_ugx: 1 })} disabled={itemFields.length >= 30}>Add item</Button></div><div className="field-grid"><label>Transaction date<input type="date" {...register('transaction_date')} required /></label><label>Payment deadline<input type="date" {...register('due_date')} /></label></div><div className="field-grid"><label>Total value (UGX)<input type="number" min="1" step="1" {...register('total_ugx', { valueAsNumber: true })} required /></label><label>Amount recorded as paid (UGX)<input type="number" min="0" step="1" {...register('paid_ugx', { valueAsNumber: true })} required /></label></div><label>Delivery information (optional)<textarea rows={3} {...register('delivery_notes')} placeholder="How and when were the goods delivered?" /></label><div className="balance-preview">Calculated outstanding balance <strong>{ugx(Math.max(0, total - paid))}</strong></div><p className="field-hint">The initial paid amount is a business report; MyBizVault has not verified the payment.</p>{Boolean(error) && <ErrorBlock error={error} />}<div className="form-actions"><Button type="submit" disabled={busy || !customers.length}>{busy ? 'Saving…' : 'Save transaction'}</Button><Button asChild variant="ghost"><Link to="/transactions">Cancel</Link></Button></div></form><div className="card guidance-card"><CircleAlert size={21} /><h3>What happens next?</h3><p>A payment receipt is created for any amount recorded as paid. If a balance remains, an agreement draft is created. Nothing is sent without your action.</p></div></div></>
}

type CustomerFields = { display_name: string; phone: string; email: string; notes: string }
function CustomersPage({ membership }: { membership: Membership }) {
  const queryClient = useQueryClient(), [error, setError] = useState<unknown>(null), [busy, setBusy] = useState(false)
  const [editing, setEditing] = useState<string | null>(null)
  const { data = [], isPending, error: loadError } = useQuery({ queryKey: ['customers', membership.business_id], queryFn: () => getCustomers(membership.business_id), enabled: membership.can_manage_customers || membership.can_create_transactions })
  const { register, handleSubmit, reset } = useForm<CustomerFields>()
  const submit = handleSubmit(async values => {
    if (!values.phone?.trim() && !values.email?.trim()) { setError(new Error('Enter a phone number or email address.')); return }
    setBusy(true); setError(null)
    try { if (editing) await updateCustomer(membership.business_id, editing, values); else await createCustomer(membership.business_id, values); await queryClient.invalidateQueries({ queryKey: ['customers', membership.business_id] }); await queryClient.invalidateQueries({ queryKey: ['transactions', membership.business_id] }); reset(); setEditing(null) }
    catch (failure) { setError(failure) } finally { setBusy(false) }
  })
  return <><SectionIntro label="BUSINESS RECORDS" title="Customers" description="Business-managed contacts connected to your transactions. Customers do not have app accounts." /><div className="module-layout"><div className="card module-card"><SectionHeading title="Customer records" />{!membership.can_manage_customers && !membership.can_create_transactions ? <EmptyState title="Access not granted" detail="Ask your business owner for customer access." /> : isPending ? <p className="muted-padding">Loading customers…</p> : loadError ? <ErrorBlock error={loadError} /> : data.length ? <div className="module-items">{data.map((item: Counterparty) => <div className="module-item" key={item.id}><span className="module-item-icon"><Users size={18} /></span><div><strong>{item.display_name}</strong><small>{item.phone || item.email || "Contact details restricted"}</small></div>{membership.can_manage_customers && <button type="button" className="text-link" onClick={() => { setEditing(item.id); reset({ display_name: item.display_name, phone: item.phone || "", email: item.email || "", notes: item.notes || "" }) }}>Edit</button>}</div>)}</div> : <EmptyState title="No customers yet" detail="Add the person or business you will document a transaction with." />}</div>{membership.can_manage_customers && <form className="card form-card form-stack" onSubmit={submit}><h3>{editing ? "Edit customer" : "Add a customer"}</h3><label>Name<input {...register('display_name')} required minLength={2} /></label><label>Phone<input type="tel" {...register('phone')} placeholder="+256…" /></label><label>Email<input type="email" {...register('email')} /></label><label>Notes (optional)<textarea rows={3} {...register('notes')} /></label>{Boolean(error) && <ErrorBlock error={error} />}<Button type="submit" disabled={busy}>{busy ? 'Saving…' : editing ? 'Save changes' : 'Save customer'}</Button>{editing && <Button type="button" variant="ghost" onClick={() => { setEditing(null); reset() }}>Cancel editing</Button>}<p className="field-hint">A phone number or email is required. This record does not create a customer login.</p></form>}</div></>
}

type StaffFields = { full_name: string; email: string; password: string; can_view_transactions: boolean; can_create_transactions: boolean; can_manage_customers: boolean; can_manage_agreements: boolean; can_view_documents: boolean; can_manage_documents: boolean; can_manage_obligations: boolean }
function StaffRow({ member, businessId }: { member: StaffMember; businessId: string }) {
  const queryClient = useQueryClient(), [error, setError] = useState<unknown>(null), [busy, setBusy] = useState(false)
  const [permissions, setPermissions] = useState({ can_view_transactions: member.can_view_transactions, can_create_transactions: member.can_create_transactions, can_manage_customers: member.can_manage_customers, can_manage_agreements: member.can_manage_agreements, can_view_documents: member.can_view_documents, can_manage_documents: member.can_manage_documents, can_manage_obligations: member.can_manage_obligations, is_active: member.is_active })
  const save = async () => { setBusy(true); setError(null); try { await updateStaff(businessId, member.id, permissions); await queryClient.invalidateQueries({ queryKey: ['staff', businessId] }) } catch (failure) { setError(failure) } finally { setBusy(false) } }
  return <div className="staff-row"><div><strong>{member.full_name}</strong><small>{member.email}</small></div><div className="permission-grid"><label><input type="checkbox" checked={permissions.can_view_transactions} disabled={permissions.can_create_transactions || permissions.can_manage_agreements || permissions.can_manage_obligations} onChange={event => setPermissions({ ...permissions, can_view_transactions: event.target.checked })} /> View transactions</label><label><input type="checkbox" checked={permissions.can_create_transactions} onChange={event => setPermissions({ ...permissions, can_create_transactions: event.target.checked, can_view_transactions: event.target.checked || permissions.can_view_transactions })} /> Create transactions</label><label><input type="checkbox" checked={permissions.can_manage_customers} onChange={event => setPermissions({ ...permissions, can_manage_customers: event.target.checked })} /> Manage customers</label><label><input type="checkbox" checked={permissions.can_manage_agreements} onChange={event => setPermissions({ ...permissions, can_manage_agreements: event.target.checked, can_view_transactions: event.target.checked || permissions.can_view_transactions })} /> Manage agreements</label><label><input type="checkbox" checked={permissions.can_view_documents} disabled={permissions.can_manage_documents} onChange={event => setPermissions({ ...permissions, can_view_documents: event.target.checked })} /> View documents</label><label><input type="checkbox" checked={permissions.can_manage_documents} onChange={event => setPermissions({ ...permissions, can_manage_documents: event.target.checked, can_view_documents: event.target.checked || permissions.can_view_documents })} /> Manage documents</label><label><input type="checkbox" checked={permissions.can_manage_obligations} onChange={event => setPermissions({ ...permissions, can_manage_obligations: event.target.checked, can_view_transactions: event.target.checked || permissions.can_view_transactions })} /> Manage obligations</label><label><input type="checkbox" checked={permissions.is_active} onChange={event => setPermissions({ ...permissions, is_active: event.target.checked })} /> Active</label></div>{Boolean(error) && <ErrorBlock error={error} />}<Button size="small" variant="outline" disabled={busy} onClick={save}>{busy ? 'Saving…' : 'Save permissions'}</Button></div>
}

function SettingsPage({ membership }: { membership: Membership }) {
  const queryClient = useQueryClient(), [name, setName] = useState(membership.business_name), [error, setError] = useState<unknown>(null), [busy, setBusy] = useState(false)
  const [businessPhone, setBusinessPhone] = useState(membership.business_phone || '')
  const [businessEmail, setBusinessEmail] = useState(membership.business_email || '')
  const { data: staff = [], isPending, error: staffError } = useQuery({ queryKey: ['staff', membership.business_id], queryFn: () => getStaff(membership.business_id), enabled: membership.role === 'owner' })
  const { register, handleSubmit, reset } = useForm<StaffFields>({ defaultValues: { can_view_transactions: false, can_create_transactions: false, can_manage_customers: false, can_manage_agreements: false, can_view_documents: false, can_manage_documents: false, can_manage_obligations: false } })
  const addStaff = handleSubmit(async values => { setBusy(true); setError(null); try { await createStaff(membership.business_id, { ...values, can_view_documents: values.can_view_documents || values.can_manage_documents, can_view_transactions: values.can_view_transactions || values.can_manage_obligations }); await queryClient.invalidateQueries({ queryKey: ['staff', membership.business_id] }); reset() } catch (failure) { setError(failure) } finally { setBusy(false) } })
  const rename = async () => { setBusy(true); setError(null); try { await updateBusiness(membership.business_id, { name, phone: businessPhone, email: businessEmail }); await queryClient.invalidateQueries({ queryKey: ['me'] }) } catch (failure) { setError(failure) } finally { setBusy(false) } }
  return <><SectionIntro label="BUSINESS WORKSPACE" title="Settings" description="Business identity and staff access are controlled by the owner." />{membership.role !== 'owner' ? <div className="card module-card"><h3>Your access</h3><p>Transactions: {membership.can_view_transactions ? 'view' : 'no access'} · Create: {membership.can_create_transactions ? 'allowed' : 'not allowed'} · Customers: {membership.can_manage_customers ? 'manage' : 'no management'} · Agreements: {membership.can_manage_agreements ? 'manage' : 'no access'} · Documents: {membership.can_manage_documents ? 'manage' : membership.can_view_documents ? 'view' : 'no access'} · Obligations: {membership.can_manage_obligations ? 'manage' : 'view only'}</p></div> : <div className="settings-stack"><div className="card form-card"><h3>Business profile</h3><div className="inline-form"><label>Business name<input value={name} onChange={event => setName(event.target.value)} minLength={2} maxLength={160} /></label><label>Business phone<input type="tel" value={businessPhone} onChange={event => setBusinessPhone(event.target.value)} maxLength={32} /></label><label>Business email<input type="email" value={businessEmail} onChange={event => setBusinessEmail(event.target.value)} /></label><Button onClick={rename} disabled={busy || name.trim().length < 2}>Save business profile</Button></div></div><div className="card form-card"><SectionHeading title="Authorised staff" /><p className="field-hint">Staff start with no permissions. They do not gain access to business settings or document records automatically.</p>{isPending ? <p>Loading staff…</p> : staffError ? <ErrorBlock error={staffError} /> : staff.length ? staff.map(member => <StaffRow key={member.id} member={member} businessId={membership.business_id} />) : <EmptyState title="No staff yet" detail="Add a staff member below and assign only the access they need." />}</div><form className="card form-card form-stack" onSubmit={addStaff}><h3>Add staff member</h3><div className="field-grid"><label>Full name<input {...register('full_name')} required minLength={2} /></label><label>Email<input type="email" {...register('email')} required /></label></div><label>Initial password<input type="password" {...register('password')} minLength={12} required autoComplete="new-password" /></label><div className="permission-grid"><label><input type="checkbox" {...register('can_view_transactions')} /> View transactions</label><label><input type="checkbox" {...register('can_create_transactions')} /> Create transactions</label><label><input type="checkbox" {...register('can_manage_customers')} /> Manage customers</label><label><input type="checkbox" {...register('can_manage_agreements')} /> Manage agreements</label><label><input type="checkbox" {...register('can_view_documents')} /> View documents</label><label><input type="checkbox" {...register('can_manage_documents')} /> Manage documents</label><label><input type="checkbox" {...register('can_manage_obligations')} /> Manage obligations</label></div>{Boolean(error) && <ErrorBlock error={error} />}<Button type="submit" disabled={busy}>{busy ? 'Adding…' : 'Add staff'}</Button><p className="field-hint">Share the initial password with the staff member through a channel you trust. Email delivery is not yet integrated.</p></form></div>}</>
}

function ActivityPage({ membership }: { membership: Membership }) { const { data = [], isPending, error } = useQuery({ queryKey: ['transactions', membership.business_id], queryFn: () => getTransactions(membership.business_id), enabled: membership.can_view_transactions }); return <><SectionIntro label="BUSINESS WORKSPACE" title="Activity" description="Recent transaction records for this business." /><div className="card module-card">{!membership.can_view_transactions ? <EmptyState title="Access not granted" detail="Ask the owner for transaction access." /> : isPending ? <p>Loading activity…</p> : error ? <ErrorBlock error={error} /> : data.length ? <TransactionList items={data.slice(0, 10)} /> : <EmptyState title="Nothing recorded yet" detail="Saved transactions will appear here." />}</div></> }
function MorePage() { return <><SectionIntro label="BUSINESS WORKSPACE" title="More" description="Explore your business tools." /><div className="more-grid">{[...nav.slice(2), { label: 'Settings', path: '/settings', icon: Settings2 }].map(({ label, path, icon: Icon }) => <Link className="more-link" key={path} to={path}><Icon size={20} /><span>{label}</span><ChevronRight size={17} /></Link>)}</div></> }
function CustomerReviewPage() { return <div className="review-page"><header className="review-header"><Logo /><span className="review-header-note"><ShieldCheck size={16} /> Agreement review preview</span></header><main className="review-container"><div className="review-label">DESIGN SHELL · NO LIVE AGREEMENT</div><div className="review-intro"><p className="eyebrow">EXAMPLE INVITATION</p><h1>Review your agreement</h1><p>This illustrative page has no live agreement. A real invitation opens a separate, transaction-specific review link.</p></div><div className="review-card"><div className="review-card-head"><div><small>EXAMPLE REFERENCE</small><strong>MBV-DEMO-084</strong></div><StatusPill tone="amber">Illustrative draft</StatusPill></div><div className="review-card-body"><h2>Credit sale agreement</h2><p>Mike's Wholesale proposes to supply wholesale goods to Bosco Okello for {ugx(1_000_000)}. An initial {ugx(700_000)} is recorded as paid. The remaining {ugx(300_000)} is due seven days after the transaction date.</p><div className="review-amounts"><div><span>Total value</span><strong>{ugx(1_000_000)}</strong></div><div><span>Recorded as paid</span><strong>{ugx(700_000)}</strong></div><div className="amount-due"><span>Balance due</span><strong>{ugx(300_000)}</strong></div></div><div className="review-disclaimer"><CircleAlert size={19} /><span>Illustrative terms only. A real invitation must show the complete agreement version before any response.</span></div></div></div><div className="review-actions"><h3>Your response</h3><p>These example actions remain disabled. Use a live invitation link to respond to a real draft.</p><div className="review-buttons"><Button disabled>Accept agreement</Button><Button variant="outline" disabled>Request correction</Button><Button variant="ghost" disabled>Reject</Button></div><small>Actions are disabled in this preview.</small></div></main></div> }

export default function App() {
  const queryClient = useQueryClient()
  const location = useLocation()
  const { data: user, isPending, error, refetch } = useQuery({ queryKey: ['me'], queryFn: getMe, retry: false })
  const [selectedBusiness, selectBusiness] = useState<string | null>(null)
  const membership = user?.memberships.find(item => item.business_id === selectedBusiness) ?? user?.memberships[0]
  if (location.pathname === '/review/demo' || location.pathname === '/review/invite' || location.pathname === '/review/proposal') return <Routes><Route path="/review/demo" element={<CustomerReviewPage />} /><Route path="/review/invite" element={<ExternalAgreementPage />} /><Route path="/review/proposal" element={<ProposalReviewPage />} /></Routes>
  if (isPending) return <div className="boot-screen"><Logo /><p>Opening your workspace…</p></div>
  if (error && !(axios.isAxiosError(error) && error.response?.status === 401)) return <div className="boot-screen"><Logo /><ErrorBlock error={error} /><Button onClick={() => refetch()}>Try again</Button></div>
  if (!user) return <AuthScreen onSuccess={() => { queryClient.invalidateQueries({ queryKey: ['me'] }) }} />
  if (!membership) return <div className="boot-screen"><Logo /><p>Your account has no active business membership. Ask the business owner to restore access.</p><Button onClick={async () => { await logout(); await clearUserDrafts(user.id).catch(() => {}); queryClient.clear(); window.location.reload() }}>Sign out</Button></div>
  return <DashboardLayout user={user} membership={membership} selectBusiness={selectBusiness}><Routes><Route path="/" element={<HomePage user={user} membership={membership} />} /><Route path="/activity" element={<ActivityPage membership={membership} />} /><Route path="/transactions" element={<TransactionsPage membership={membership} />} /><Route path="/transactions/new" element={<NewTransactionPage membership={membership} userId={user.id} />} /><Route path="/transactions/:transactionId" element={<TransactionDetailPage membership={membership} />} /><Route path="/customers" element={<CustomersPage membership={membership} />} /><Route path="/payments" element={<ObligationsPage membership={membership} mode="payments" />} /><Route path="/negotiations" element={<ObligationsPage membership={membership} mode="negotiations" />} /><Route path="/disputes" element={<ObligationsPage membership={membership} mode="disputes" />} /><Route path="/agreements" element={<AgreementsPage membership={membership} />} /><Route path="/vault" element={<VaultPage membership={membership} />} /><Route path="/legal-assistant" element={<LegalAssistantPage />} /><Route path="/lawyers" element={<FindLawyerPage membership={membership} />} /><Route path="/settings" element={<SettingsPage key={membership.business_id} membership={membership} />} /><Route path="/more" element={<MorePage />} /><Route path="*" element={<EmptyState title="Page not found" detail="This page is not part of your workspace." action={<Button asChild><Link to="/">Return home</Link></Button>} />} /></Routes></DashboardLayout>
}
